// CodegenRunner — runs generators against a loaded model and writes their files.
//
// The write decision comes from a HASH MANIFEST of what this generator previously
// wrote, not from the <auto-generated/> marker. The marker rule it replaces was wrong
// in both directions: a hand-EDITED generated file keeps its marker, so the one case
// worth protecting was overwritten silently; and a file this generator wrote whose
// template later stopped emitting the marker was refused as though it were somebody's
// hand-written source.
//
// Mirrors codegen-ts's overwrite policy minus the three-way merge, which stays TS-only
// (it needs a full snapshot of prior content plus `git merge-file`). Here the outcome
// for a diverged file is a refusal rather than a merge — see HashManifest.

using MetaObjects.Meta;

namespace MetaObjects.Codegen;

/// <summary>Runs a generator set and writes the emitted files.</summary>
public static class CodegenRunner
{
    /// <summary>Files carrying this marker are owned by codegen and safe to overwrite.</summary>
    public const string GeneratedMarker = "<auto-generated/>";

    public sealed record WriteResult(string Path, string Status);
    public sealed record RunResult(IReadOnlyList<WriteResult> Files, IReadOnlyList<string> Warnings)
    {
        /// <summary>Absolute paths emitted by an entry declaring <see cref="HandEdits.Overwrite"/>:
        /// <c>verify --codegen</c> reads it to tell that gen replaces an edit to one of them.</summary>
        public IReadOnlySet<string> OverwritePaths { get; init; } = new HashSet<string>();
    }

    public static RunResult Run(GenConfig config, MetaRoot root, IReadOnlyList<IGenerator> generators)
        => Run(config, root, generators, OutRootFor(config));

    /// <summary>
    /// The directory a generator's files are written under: its own <see cref="IGenerator.OutDir"/>
    /// when it names one (ADR-0034 Amendment 9), else the run's <see cref="GenConfig.OutDir"/>.
    /// </summary>
    internal static Func<IGenerator, string> OutRootFor(GenConfig config) =>
        g => g.OutDir is { Length: > 0 } own ? Path.GetFullPath(own) : config.OutDir;

    /// <summary><see cref="Run(GenConfig, MetaRoot, IReadOnlyList{IGenerator})"/> with the output
    /// directory of each generator chosen by <paramref name="outRoot"/>: the drift gate points
    /// every entry at a temporary tree of its own.</summary>
    internal static RunResult Run(
        GenConfig config, MetaRoot root, IReadOnlyList<IGenerator> generators, Func<IGenerator, string> outRoot)
    {
        var warnings = new List<string>();
        var ctx = new GenContext
        {
            // FR-044: an object.report is never in the entity set. Dropped here, at the set
            // every generator reads, and not per generator: a report may declare a read-only
            // `source.rdb @kind: view` (R5), which would otherwise pass every source-keyed
            // gate and emit an empty projection tier (routes, allowlist, names).
            //
            // A view-backed report DOES generate its keyless row and DbContext mapping
            // (Plan 2), and its filter allowlist and read-only routes (Plan 3). The four
            // generators that emit those ask for the report's row model themselves, through
            // ReportRows, so every other generator stays report-free without having to know
            // what a report is.
            //
            // FR-023: an object a metadata dependency owns is dropped here too, for the same reason
            // and at the same place (root.InScope; ImportScope.InScope is the rule). It loaded so the
            // project's own model resolves against it, but it is not this project's to generate.
            Entities = root.Objects().Where(o => !o.IsReport() && root.InScope(o)).ToList(),
            Root = root,
            Config = config,
            Warn = warnings.Add,
            Generators = generators,
        };

        // Refuse before any generator runs — the one choke point that sees the WHOLE
        // entity set every DbSet/route/finder-emitting generator below reads from.
        // A view-backed report gets a DbSet too, so it is part of the collision check.
        CSharpNaming.AssertNoCollectionNameCollisions(
            [.. ctx.Entities, .. root.Objects().Where(o => ReportRows.IsViewBacked(o) && root.InScope(o))]);

        Directory.CreateDirectory(config.OutDir);
        var results = new List<WriteResult>();
        // Two generators (or a name collision between an entity and a value-object
        // POCO) writing the same path would silently clobber each other; error
        // instead, mirroring codegen-ts's runGen duplicate-path check.
        var emitted = new Dictionary<string, string>(StringComparer.Ordinal);
        var refused = new List<string>();
        var adopted = new List<string>();
        var overwritePaths = new HashSet<string>(StringComparer.Ordinal);
        var untracked = 0;
        // Captured BEFORE any write, because the first write creates the manifest —
        // read it afterwards and every project looks migrated.
        var hadManifest = config.GenStateDir is null || HashManifest.Exists(config.GenStateDir);

        foreach (var generator in generators)
        {
            var genRoot = outRoot(generator);
            // An entry with its own directory reports its files by that directory, so a reader
            // can tell the api reference's README.md from one under --out.
            var shown = generator.OutDir is { Length: > 0 } own ? own.TrimEnd('/', '\\') + "/" : "";
            foreach (var file in generator.Generate(ctx))
            {
                var full = Path.GetFullPath(Path.Combine(genRoot, file.Path));
                if (!emitted.TryAdd(full, generator.Name))
                    throw new InvalidOperationException(
                        $"duplicate generated output path \"{file.Path}\" — emitted by both " +
                        $"\"{emitted[full]}\" and \"{generator.Name}\".");
                if (generator.HandEdits == HandEdits.Overwrite) overwritePaths.Add(full);
                // The manifest key. Project-root-relative when the caller names a project,
                // so two runs with different --out cannot collide on one entry inside the
                // single manifest that is anchored on that project. `file.Path` rides
                // along as the legacy spelling — it is what the manifest used to be keyed
                // by, and it is still what a refusal is REPORTED as (the name the reader
                // sees under --out).
                //
                // BOTH SIDES NORMALISED THE SAME WAY. `full` and ProjectRoot both come
                // from Path.GetFullPath — normalised, NOT link-resolved — so the relative
                // path between them is the path between the two directories. Resolving
                // only one side would, under a directory symlink, walk every key out of
                // the project; nothing would then match and a drift gate would report
                // "in sync" over stale output.
                var key = config.ProjectRoot is { } projectRoot
                    ? Path.GetRelativePath(Path.GetFullPath(projectRoot), full)
                    : file.Path;
                // A file written OUTSIDE the project has no place in the project's
                // manifest: its key would be `../`-relative and committed into
                // .hashes.json. It gets the manifest-less rule a run with no project gets.
                var outside = config.ProjectRoot is not null
                    && (key.StartsWith("..", StringComparison.Ordinal) || Path.IsPathRooted(key));
                if (outside) untracked++;
                var status = WriteOne(
                    outside ? config with { GenStateDir = null } : config,
                    full, file.Path, key, file.Content, warnings,
                    overwriteEdits: generator.HandEdits == HandEdits.Overwrite);
                var reported = shown + file.Path;
                if (status == OverwroteEdit)
                {
                    warnings.Add(
                        $"overwrote hand-edited {reported} with fresh output (handEdits: Overwrite on {generator.Name})");
                    status = "written";
                }
                results.Add(new WriteResult(reported, status));
                if (status == "refused") refused.Add(reported);
                else if (status == "adopted") adopted.Add(reported);
            }
        }

        if (config.SweepOrphans && config.GenStateDir is { } genState && config.ProjectRoot is { } project
            && config.Baseline != "adopt")
        {
            // Every directory a generator of this run wrote into, labelled as its files are
            // reported. The run's own --out is always one of them.
            var dirs = new List<(string Dir, string Label)> { (config.OutDir, "") };
            foreach (var g in generators)
                dirs.Add((outRoot(g), g.OutDir is { Length: > 0 } own ? own.TrimEnd('/', '\\') + "/" : ""));
            var swept = OrphanSweep.Sweep(genState, project, dirs, emitted.Keys.ToHashSet(StringComparer.Ordinal),
                OverwriteDirs(generators, outRoot, config.OutDir));
            foreach (var path in swept.Removed) results.Add(new WriteResult(path, "removed"));
            foreach (var path in swept.Discarded)
                warnings.Add($"deleted hand-edited {path}, which no generator emits any more (handEdits: Overwrite)");
            if (swept.Refused.Count > 0) warnings.Add(OrphanSweep.RefusedMessage(swept.Refused));
        }

        if (untracked > 0)
            warnings.Add(
                $"{untracked} generated file(s) were written outside the project root and are " +
                "not recorded in .metaobjects/.gen-state/.hashes.json, so hand-edit protection " +
                "does not apply to them beyond the <auto-generated/> marker rule.");
        ReportRefusals(refused, hadManifest, warnings);
        ReportAdoptions(adopted, warnings);
        return new RunResult(results, warnings) { OverwritePaths = overwritePaths };
    }

    /// <summary>
    /// Decide and perform the write for one file.
    /// <para>
    /// With a <see cref="GenConfig.GenStateDir"/> the decision comes from the hash
    /// manifest: identical content is <c>unchanged</c>; a file still hashing to what we
    /// recorded is safe to overwrite; anything else — edited, or never recorded — is
    /// <c>refused</c>. A refusal deliberately does NOT record the current content, since
    /// that would make the file look pristine next run and turn this into a silent
    /// overwrite one run later.
    /// </para>
    /// <para>
    /// With no state dir the legacy marker rule stands, preserving the previous behaviour
    /// (and its status string) for programmatic callers.
    /// </para>
    /// </summary>
    private static string WriteOne(
        GenConfig config, string full, string relPath, string key, string content,
        List<string> warnings, bool overwriteEdits = false)
    {
        // The out-dir-relative spelling this file may already be recorded under, from
        // before keys became project-root-relative. `null` once the two agree, so an
        // unmigrated project does no legacy work at all.
        var legacyKey = string.Equals(key, relPath, StringComparison.Ordinal) ? null : relPath;
        var exists = File.Exists(full);

        if (config.GenStateDir is null)
        {
            if (exists && !File.ReadAllText(full).Contains(GeneratedMarker, StringComparison.Ordinal))
            {
                warnings.Add($"refusing to overwrite hand-written file: {relPath}");
                return "skipped-handwritten";
            }
            WriteFile(full, content);
            // "written" for both a create and an overwrite, preserving the exact status
            // vocabulary this path had before the manifest existed — callers key on it.
            return "written";
        }

        if (!exists)
        {
            WriteFile(full, content);
            HashManifest.Record(config.GenStateDir, key, content, legacyKey);
            // "written", not "new": this port's status vocabulary does not distinguish a
            // create from an overwrite, and callers key on it. The manifest ADDS
            // "unchanged" and "refused" without redefining what was already there —
            // renaming these would be an API change unrelated to the defect being fixed.
            return "written";
        }

        var current = File.ReadAllText(full);
        if (current == content)
        {
            // Record it: a first run over already-correct output should leave the file
            // recognisable as ours next time.
            HashManifest.Record(config.GenStateDir, key, content, legacyKey);
            return "unchanged";
        }

        if (HashManifest.IsPristine(config.GenStateDir, key, current, legacyKey))
        {
            WriteFile(full, content);
            HashManifest.Record(config.GenStateDir, key, content, legacyKey);
            return "written";
        }

        // Edited since we wrote it, and the entry says to discard hand edits. A file we have
        // no record of writing is never ours to replace, whatever the setting.
        if (overwriteEdits && HashManifest.IsRecorded(config.GenStateDir, key, legacyKey))
        {
            WriteFile(full, content);
            HashManifest.Record(config.GenStateDir, key, content, legacyKey);
            return OverwroteEdit;
        }

        // …unless the caller explicitly adopted what is on disk. Placed HERE, at the
        // refusal, rather than earlier: adopting can then only ever convert a refusal into
        // a recorded baseline, leaving "unchanged" and the pristine overwrite exactly as
        // they are, so passing it cannot freeze a project's regeneration.
        if (config.Baseline == "adopt")
        {
            // `current`, never `content`: recording fresh output would claim we wrote a
            // file we did not, and the next run would read the adopter's file as edited
            // and refuse all over again — the loop this mode exists to end.
            HashManifest.Record(config.GenStateDir, key, current, legacyKey);
            return "adopted";
        }

        return "refused";
    }

    /// <summary>The internal status of a hand edit replaced under <see cref="HandEdits.Overwrite"/>;
    /// reported as <c>written</c> with a warning naming the file.</summary>
    private const string OverwroteEdit = "overwrote-edit";

    /// <summary>
    /// The output directories whose edited orphans the sweep may delete: those every generator of
    /// the run writing into them declares <see cref="HandEdits.Overwrite"/>. The manifest does not
    /// record which generator wrote a file, so one entry that keeps hand edits protects the whole
    /// directory.
    /// </summary>
    internal static IReadOnlySet<string> OverwriteDirs(
        IReadOnlyList<IGenerator> generators, Func<IGenerator, string> outRoot, string runOutDir)
    {
        var verdict = new Dictionary<string, bool>(StringComparer.Ordinal);
        foreach (var g in generators)
        {
            var dir = Path.GetFullPath(outRoot(g));
            var overwrites = g.HandEdits == HandEdits.Overwrite;
            verdict[dir] = verdict.TryGetValue(dir, out var prior) ? prior && overwrites : overwrites;
        }
        return verdict.Where(kv => kv.Value).Select(kv => kv.Key).ToHashSet(StringComparer.Ordinal);
    }

    private static void WriteFile(string full, string content)
    {
        var dir = Path.GetDirectoryName(full);
        if (dir is not null) Directory.CreateDirectory(dir);
        File.WriteAllText(full, content);
    }

    /// <summary>
    /// Report refusals ONE of two ways. A project with no manifest predates the manifest
    /// being committed: every refusal shares the same cause and the same one-line fix, so
    /// N per-file warnings would bury the instruction — the hostile-first-contact outcome
    /// that gets a tool switched off. A project that HAS a manifest is refusing because
    /// specific files were edited, and there the per-file naming is the actionable part.
    /// Self-extinguishing: once the manifest is committed, the aggregate never fires again.
    /// </summary>
    private static void ReportRefusals(List<string> refused, bool hadManifest, List<string> warnings)
    {
        if (refused.Count == 0) return;

        if (!hadManifest)
        {
            const int maxNamed = 5;
            var shown = string.Join(", ", refused.Take(maxNamed));
            var more = refused.Count > maxNamed ? $", and {refused.Count - maxNamed} more" : "";
            warnings.Add(
                $"Refused to overwrite {refused.Count} existing file(s), and this project has no " +
                $"codegen hash manifest — so codegen cannot tell your edits from its own stale " +
                $"output, and will not guess. This is the expected first run for a project " +
                $"created before the manifest was committed. ONE-TIME FIX: re-run with " +
                $"--baseline=adopt — it records the files you have as the baseline and writes " +
                $"NOTHING — then commit '.gen-state/.hashes.json' and run gen again, where the " +
                $"regeneration arrives as its own reviewable diff. Adopting DECLARES these files " +
                $"to be generated output, so an edit already inside one of them is part of the " +
                $"baseline and that regeneration will replace it — commit before you run it. " +
                $"Files: {shown}{more}.");
            return;
        }

        foreach (var relPath in refused)
        {
            warnings.Add(
                $"Refused to overwrite {relPath}: it has been edited since it was generated, or " +
                $"there is no record of generating it. Move your edits into a non-generated file, " +
                $"or delete it to accept fresh output.");
        }
    }

    /// <summary>
    /// Report a <c>--baseline=adopt</c> run. Aggregated for the same reason the no-manifest
    /// refusal is — one cause, one next step — and reported even though nothing failed,
    /// because a run that writes nothing and exits 0 is otherwise indistinguishable from a
    /// no-op, while the file it DID produce (the manifest) is the one to commit.
    /// </summary>
    private static void ReportAdoptions(List<string> adopted, List<string> warnings)
    {
        if (adopted.Count == 0) return;
        const int maxNamed = 5;
        var shown = string.Join(", ", adopted.Take(maxNamed));
        var more = adopted.Count > maxNamed ? $", and {adopted.Count - maxNamed} more" : "";
        warnings.Add(
            $"Recorded {adopted.Count} existing file(s) as the codegen baseline and wrote " +
            $"nothing. NEXT: commit '.gen-state/.hashes.json', then run gen again — these " +
            $"files regenerate normally from here, as their own reviewable diff. Adopting " +
            $"DECLARED them to be generated output: an edit already inside one is part of the " +
            $"baseline and that regeneration will replace it, so check the diff against git. " +
            $"Files: {shown}{more}.");
    }
}
